            goal: 'Att skapa ett premiumvarumärke för fiske-SUP med 2 SKU:er (11\'0" Guide Pro och 12\'6" Expedition Elite) med integrerade fiskefunktioner, riktat mot DTC-kunder och andra fiskeguider, med ett förstaårs mål på 400 sålda enheter och 320 000 USD i omsättning.',
