            background:
              'Erik Solberg, 51, är Senior Expedition Product Manager på Hurtigruten Svalbard AS, det norska kryssningsrederiet som driver 7 hybriddrivna expeditionsfartyg i Arktis. Hurtigrutens gäster (genomsnittsålder 58 år, hushållsinkomst över 350 000 USD) betalar 8 000–25 000 USD för 12-dagarsresor. Under 2023 visade gästfeedbacken att «aktiva arktiska upplevelser» var den största ouppfyllda efterfrågan — specifikt paddling i smågrupper bland isberg och längs glaciärfronter. Men vanliga SUP:ar klarar inte vatten på 2 °C, luft på -5 °C eller logistiken kring uttagning från Zodiac-båtar i isbjörnsterräng. Erik hade testat 3 märken 2022 — alla slogs ut inom 5 turer (ventilerna frös, brädorna blev sköra och en tappade luften mitt under paddling i 4 °C-vatten, vilket krävde en nödhämtning med Zodiac 800 meter från fartyget).',
