          title:
            'Paws & Paddle UK — brittiskt husdjursvarumärke lanserar hundvänlig SUP-kollektion hos 340 återförsäljare',
          customer: {
            location: 'London, Storbritannien',
            background:
              'Paws & Paddle var ett snabbväxande brittiskt husdjursvarumärke grundat av fd. djursjukvårdaren Emma Thornton 2019, med premiumhalsband, sängar och friluftsutrustning för hundar och 4,2 miljoner GBP i årlig omsättning. Den brittiska marknaden för husdjursprodukter var värd 8 miljarder GBP, och 34 % av Storbritanniens hushåll hade hundar. Emma såg en lucka: inget större husdjursvarumärke erbjöd vattensportsutrustning för hundar, trots den explosiva trenden med hundvänliga äventyr i sociala medier (hashtaggen #dogpaddle hade 430 miljoner visningar på TikTok). Emmas team hade goda relationer med 340 brittiska husdjursbutiker och mer än 50 friluftsbutiker men behövde en tillverkningspartner som kunde utveckla SUP-brädor specifikt designade för hundar med lämpliga säkerhetsfunktioner och testning.',
            goal: 'Skapa en hundvänlig SUP-serie med 3 modeller («Paws & Paddle Adventure»), säkra placering i mer än 200 brittiska butiker inom 12 månader och uppnå 1,5 miljoner GBP i grossistintäkter under det första året med 52 % marginal.',
          },
