            goal: 'Att lansera ett crowdfundingfinansierat direkt-till-konsument-SUP-varumärke kallat «Driftcraft» med en första produktionsserie på 500 brädor, nå ett finansieringsmål på £150 000 inom 45 dagar och samtidigt behålla full kreativ och operativ kontroll.',
